--- a/faiss/utils/bf16.h
+++ b/faiss/utils/bf16.h
@@ -14,6 +14,10 @@
 #include <immintrin.h>
 #endif

+#if defined(__riscv_vector)
+#include <riscv_vector.h>
+#endif
+
 namespace faiss {

 namespace {
@@ -61,7 +65,34 @@ inline void decode_bf16_simd(const uint16_t* src, float* dst, size_t n) {
         w = _mm512_slli_epi32(w, 16);
         _mm512_storeu_ps(dst + i, _mm512_castsi512_ps(w));
     }
+#elif defined(__riscv_vector)
+    // RVV fast path: mirror the AVX512 widening sequence (u16 -> zero-extended
+    // u32 -> shift left by 16) with bit-exact semantics, but carry a single
+    // back-branch per vector chunk in a fixed-VL main loop and finish with a
+    // single runtime-VL tail, so per-call taken branches drop from ~n to ~n/vl.
+    const size_t vlmax = __riscv_vsetvlmax_e16m1();
+    for (; i + vlmax <= n; i += vlmax) {
+        vuint16m1_t v = __riscv_vle16_v_u16m1(src + i, vlmax);
+        vuint32m2_t w = __riscv_vzext_vf2_u32m2(v, vlmax);
+        w = __riscv_vsll_vx_u32m2(w, 16, vlmax);
+        __riscv_vse32_v_f32m2(
+                dst + i,
+                __riscv_vreinterpret_v_u32m2_f32m2(w),
+                vlmax);
+    }
+    if (i < n) {
+        const size_t vl = __riscv_vsetvl_e16m1(n - i);
+        vuint16m1_t v = __riscv_vle16_v_u16m1(src + i, vl);
+        vuint32m2_t w = __riscv_vzext_vf2_u32m2(v, vl);
+        w = __riscv_vsll_vx_u32m2(w, 16, vl);
+        __riscv_vse32_v_f32m2(
+                dst + i,
+                __riscv_vreinterpret_v_u32m2_f32m2(w),
+                vl);
+        i += vl;
+    }
 #endif
+    // Scalar tail for the last <vl elements (and for non-RVV builds).
     for (; i < n; i++) {
         dst[i] = decode_bf16(src[i]);
     }
